function UIFightTeamSweepRewardDialog:InitComponent()
    if isNull(self.LB_Slider2.Env) then
        self.LB_Slider2:Init()
    end
    self.LT_Slider2 = self.LB_Slider2.Env

    SetButtonAction(self.Btn_Complete, Bind(self, self.OnCompleteClick))

    -- 假如有任务完成提示，把任务完成提示拿过来放到扫荡界面下面
    local dialogs = UIModule.CurrentScreen.dialogs
    for i = 0, dialogs.Count - 1, 1 do
        local dialog = dialogs[i]
        if checkNumber(dialog.Argument.id) == Constants.UITypeIds.UIFightTeamChoose then
            local taskTipsNode = dialog.transform:Find("CommonMainlineTaskTipsNode")
            if not isNull(taskTipsNode) then
                KTool.SetParent(taskTipsNode.gameObject, self.controller.gameObject, false)
            end
        end
    end
end

function UIFightTeamSweepRewardDialog:OnCompleteClick()
    cs_coroutine.start(function()
        local co = self:ShowPlayerLevelUp()
        if co then
            cs_coroutine.yield_return(co)
        end

        if self.params.needShowAnnihilationPopup then
            ResourceModule.LoadGameObjectAsync(Constants.BattleEndCompResPath.CommonAnnihilationWarPopup, function(go)
                if not KTool.IsNull(go) then
                    go.name = "CommonAnnihilationWarPopup"
                    if not KTool.IsNull(go) then
                        local scr = CfUtils.GetLuaScr(go, Constants.BattleEndCompLuaPath.CommonAnnihilationWarPopup)
                        if scr then
                            local bossId = 1
                            bossId = checkInt(self.params.regionalBossData.bossTypeId)
                            scr:FillMatchSucInfo(bossId, function()
                                KTool.SafeDelete(go)
                                UIModule.BackDialog()
                                -- goto boss panel
                                local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self.questId)
                                -- print("[扫荡] questVo", table.dump(questVo))
                                CS.Engine.Lib.KCookie.Set("UIActionSecondMapDialogtargetPointId", questVo.pointID)
                                local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
                                local vo = ActionUtils.GetRegionSecondaryMapVo(questVo.pointID)
                                local dialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.UIFightTeamChoose)
                                UIModule.CloseDialog(dialog)
                                UIModule.OpenDialog({ id = Constants.UITypeIds.UIActionSecondMapDialog, parameters = {id = vo.regionBelong}}, {
                                    {id = Constants.UITypeIds.UIActionBossCollectionDialog }
                                })
                            end)
                        end
                    end
                end
            end, true, UIModule.RootCanvas.transform)
        else
            UIModule.BackDialog()
        end
    end)
end

