--- 展示玩家经验升级信息
---@param expInfo table 经验信息 {newLv = 0, oldLv = 0, newExp = 0, oldExp = 0}
function UIFightTeamSweepRewardDialog:ShowPlayerExpInfo(expInfo, showType)
    local newLv = checkInt(expInfo.newLv)
    local oldLv = checkInt(expInfo.oldLv)
    local newExp = checkInt(expInfo.newExp)
    local oldExp = checkInt(expInfo.oldExp)

    if newLv == oldLv and newExp == oldExp then
        -- print("[结算] 玩家没加经验")
        -- 没加经验
        self.Txt_Level.text = string.format("Lv.%d", expInfo.oldLv)
        
        local expData = self:GetPlayerNextLevelExpData(expInfo.oldLv)
        local lastTotal = expData.totalExp - expData.exp
        local showExp = expInfo.oldExp - lastTotal
        self.Txt_ExpNum.text = string.format("<color=#f953b1>%d</color>/%d", showExp, expData.exp)
    
        local showProgress = showExp / expData.exp
        self.LT_Slider2:SetProgress(showProgress)
    else
        -- print("[结算] 玩家增加经验")
        -- 加经验
        if showType == PanelShowType.Animate then
            UICommonUtils.AnimateUpgrade(expInfo, Bind(self, self.GetPlayerNextLevelExpData),
                QuickUpgradeTime, NormalUpgradeTime, 0.3, self.Txt_Level, "Lv.%d", self.Txt_ExpNum, self.LT_Slider2, self.coGroupPlayerUpgrade)
        elseif showType == PanelShowType.Direct then
            self.Txt_Level.text = string.format("Lv.%d", expInfo.newLv)
            
            local expData = self:GetPlayerNextLevelExpData(expInfo.newLv)
            local lastTotal = expData.totalExp - expData.exp
            local showExp = expInfo.newExp - lastTotal
            self.Txt_ExpNum.text = string.format("<color=#f953b1>%d</color>/%d", showExp, expData.exp)
        
            local showProgress = showExp / expData.exp
            self.LT_Slider2:SetProgress(showProgress)
        end
    end
end

--- 停止动画展示玩家经验升级信息
function UIFightTeamSweepRewardDialog:StopAnimateShowPlayerExpInfo()
    if not isNull(self.coGroupPlayerUpgrade.co) then
        cs_coroutine.stop(self.coGroupPlayerUpgrade.co)
        self.coGroupPlayerUpgrade.co = nil
    end
    self.LT_Slider2:StopLerpProgress()
    if not isNull(self.coGroupPlayerUpgrade.tweener) then
        self.coGroupPlayerUpgrade.tweener:Complete()
        self.coGroupPlayerUpgrade.tweener = nil
    end
end
