--- 初始化头像节点信息
---@param cardExpInfo table 卡牌经验信息(cardExpInfo[v.playerCardId] = {lv = v.cardLevel, exp = v.cardExp})
function UIFightTeamSweepRewardDialog:ShowHeadNodeList(cardExpInfo, showType)
    local teamCardInfo = checkTable(cardExpInfo)

    local teamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
    local team = DeepCopy(teamComponent:GetTeamInfoByQuestId(self.questId))
    local teamData = team[1].cardsInfo
    -- local wave = UIBattlingCtrlMgr:GetInstance():GetBattleWave(BattleInfo.myCamp)
    -- local teamData = UIBattlingDataMgr:GetTeamListByCamp(BattleInfo.myCamp, wave)
    -- print("[结算] 队伍卡牌", table.dump(teamData, nil, 5), cardExpInfo)
    local isFirstUsed = false
    for i = 1, #teamData, 1 do
        if not IsNull(teamData[i].refId) then
            local headNode
            if isFirstUsed == false then
                isFirstUsed = true
                headNode = self.RT_HeadNode
            else
                headNode = KTool.Instantiate(self.RT_HeadRoot.gameObject, self.RT_HeadNode.gameObject)
            end
            local lb_headNode = GetLuaBehaviour(headNode.gameObject, HeadLuaPath)
            lb_headNode:Init()
            local lt_headNode = lb_headNode.Env
            local index = i    -- 战场id
            local playerCardId = teamData[i].refId
            lt_headNode:ShowHeadNode(index, playerCardId, nil, teamCardInfo[tostring(playerCardId)], showType)
        end
    end

    -- for i = #teamData + 1, #self.cacheLTHeadNode, 1 do
    --     KTool.SetActive(self.cacheLTHeadNode[i].controller.gameObject, false)
    -- end
end

function UIFightTeamSweepRewardDialog:StopAnimateShowHeadNodeList()
    for k, v in pairs(self.cacheLTHeadNode) do
        local lt_headNode = self.cacheLTHeadNode[k]
        lt_headNode:StopAnimateShowHeadNode()
    end
end
