---刷新可以挑战玩家的列表
function UIFightTeamSweepRewardDialog:RefreshLoopList(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function UIFightTeamSweepRewardDialog:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local luaIndex = index + 1
    local cell
    if luaIndex == 1 then
        -- 扫荡奖励节点
        cell = loopListView:NewListViewItem("SweepCellNode")
        local LB_cell = GetLuaBehaviour(cell.gameObject, SweepRewardsLuaPath)
        if not cell.IsInitHandlerCalled then
            cell.IsInitHandlerCalled = true
            LB_cell:Init()
        end
        local data = self.loopViewListData[luaIndex]
        local LT_cell = LB_cell.Env
        LT_cell:SetRewards(data)
        LT_cell:SetExRewards(self.params.extraRewards)
    elseif luaIndex == 2 then
        -- 任务标题节点
        cell = loopListView:NewListViewItem("TaskTitleNode")
    else
        -- 任务节点
        cell = loopListView:NewListViewItem("TaskCellNode")
        local LB_cell = GetLuaBehaviour(cell.gameObject, TaskLuaPath)
        if not cell.IsInitHandlerCalled then
            cell.IsInitHandlerCalled = true
            LB_cell:Init()
        end
        local data = self.loopViewListData[luaIndex]
        local LT_cell = LB_cell.Env
        -- print("[大乱斗] cell data", table.dump(data, nil, 5))
        LT_cell:ShowTaskNode(data.taskId, data, 3)
    end

    return cell
end

function UIFightTeamSweepRewardDialog:GetPlayerNextLevelExpData(fromLv)
    return CardConfMgr:GetInstance():GetPlayerExpByLevelId(fromLv + 1, 1)
end

function UIFightTeamSweepRewardDialog:ShowPlayerLevelUp()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if playerComponent then
        return playerComponent:ShowRewardsSpecialDialog()
    end
    return nil
end

return UIFightTeamSweepRewardDialog


